package com.campusnova.controller; import com.campusnova.dto.*; import com.campusnova.model.*; import com.campusnova.repository.*; import com.campusnova.service.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController { private final AuthService auth; private final FaqService faqs; private final CategoryRepository categories; private final AnnouncementRepository announcements; private final ChatHistoryRepository history; public AdminController(AuthService a,FaqService f,CategoryRepository c,AnnouncementRepository an,ChatHistoryRepository h){auth=a;faqs=f;categories=c;announcements=an;history=h;} private void guard(String t){if(!auth.valid(t))throw new SecurityException("Administrator login required");} @PostMapping("/login") public Map<String,String> login(@RequestBody LoginRequest r){return Collections.singletonMap("token",auth.login(r));}@PostMapping("/logout") public void logout(@RequestHeader("X-Admin-Token")String t){auth.logout(t);}@PostMapping("/faqs") public Faq add(@RequestHeader("X-Admin-Token")String t,@RequestBody FaqRequest r){guard(t);return faqs.save(r);}@PutMapping("/faqs/{id}") public Faq update(@RequestHeader("X-Admin-Token")String t,@PathVariable Long id,@RequestBody FaqRequest r){guard(t);return faqs.update(id,r);}@DeleteMapping("/faqs/{id}") public void delete(@RequestHeader("X-Admin-Token")String t,@PathVariable Long id){guard(t);faqs.delete(id);}@GetMapping("/categories") public List<Category> cats(@RequestHeader("X-Admin-Token")String t){guard(t);return categories.findAll();}@PostMapping("/announcements") public Announcement announcement(@RequestHeader("X-Admin-Token")String t,@RequestBody Announcement a){guard(t);return announcements.save(a);}@GetMapping("/analytics") public Map<String,Object> analytics(@RequestHeader("X-Admin-Token")String t){guard(t);long total=history.count(),answered=history.countByAnswered(true);Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("totalQuestions",total);m.put("answered",answered);m.put("unanswered",total-answered);m.put("outOfDomain",history.countByOutOfDomain(true));m.put("directFaq",history.countByResponseType("DIRECT_FAQ"));m.put("aiRag",history.countByResponseType("AI_RAG"));m.put("knowledgeGaps",history.findTop20ByAnsweredFalseOrderByCreatedAtDesc());m.put("successRate",total==0?0:Math.round(answered*100.0/total));m.put("recentQueries",history.findAll());return m;} }
